ALLOWED = {'propext','Classical.choice','Quot.sound'}
PACKED_NAMES = ['AEGIS.CvSPackedGramV1.quad_lower','AEGIS.CvSPackedGramV1.quad_lower_complex']
def audit(actual, ring):
    packed = [line for line in ring.splitlines() if any(line.startswith("'"+n+"' ") for n in PACKED_NAMES)]
    log = actual+'\n'+'\n'.join(packed)
    if re.search(r'sorryAx|\bsorry\b|\badmit\b',log):raise ValueError('SORRYAX_OR_PROOF_HOLE')
    rows=[]
    for name in NAMES:
        prefix=re.escape("'"+name+"'")
        matches=re.findall(prefix+r" depends on axioms: \[([^\]]*)\]",log)
        empty=re.search(prefix+r" does not depend on any axioms",log)
        if not matches and not empty:raise ValueError('MISSING_AXIOM_AUDIT '+name)
        ax=set()
        for group in matches:ax.update(x.strip() for x in group.split(',') if x.strip())
        if not ax<=ALLOWED:raise ValueError('UNEXPECTED_AXIOMS '+name+' '+repr(ax))
        rows.append({'theorem':name,'axioms':sorted(ax)})
    return rows
if __name__=='__main__':
    for row in audit(Path('actual-row-bridge.log').read_text(),Path('ring.log').read_text()):
        print('SOURCE_ROW_AXIOM_AUDIT_PASS',row['theorem'],row['axioms'])
    print('ACTUAL_CVS_ROW_SOURCE_REPLAY_PASS; FIRST_COLUMN_OUTPUT_ENTRIES=139; FULL_Q80_ACTUAL_MEMBERSHIP=NOT_YET_PROVED')
